graph_mermaid:
---
config:
  flowchart:
    curve: linear
---
graph TD;
	__start__([<p>__start__</p>]):::first
	plan(plan)
	validate_decision(validate_decision)
	execute_tool(execute_tool)
	validate_fact(validate_fact)
	route(route)
	finalize(finalize)
	__end__([<p>__end__</p>]):::last
	__start__ --> plan;
	execute_tool -.-> finalize;
	execute_tool -.-> validate_fact;
	plan -.-> finalize;
	plan -.-> validate_decision;
	route -.-> finalize;
	route -.-> plan;
	validate_decision -.-> execute_tool;
	validate_decision -.-> finalize;
	validate_fact --> route;
	finalize --> __end__;
	classDef default fill:#f2f0ff,line-height:1.2
	classDef first fill-opacity:0
	classDef last fill:#bfb6fc
